$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot; $apiExe=Join-Path $root '.data\bin\sewara-api.exe'; $apiURL='http://127.0.0.1:8099'; $tmpDir=Join-Path $env:TEMP 'opencode'
New-Item -ItemType Directory -Force -Path $tmpDir | Out-Null
$env:PATH="$env:LOCALAPPDATA\Programs\DockerDesktop\resources\bin;$env:PATH"
$TA='a0000000-0000-0000-0000-000000000001';$TB='b0000000-0000-0000-0000-000000000001';$hash='$2a$10$GCmHsmqVk3cqwXmf0AVWueY8h0JHD1zo0mr.tl0F/CH0dI/01mYEu'
function Sql([string]$q){$o=docker exec sewara-staging-db psql -U sewara -d sewara -Atq -c $q 2>&1;if($LASTEXITCODE -ne 0){throw "psql gagal: $q`n$($o -join "`n")"};return ($o -join "`n").Trim()}
function Invoke-Api([string]$method,[string]$path,[string]$cookie,[string]$body=''){$out=Join-Path $tmpDir 'pelanggan-api.bin';$args=@('-s','--max-time','20','-o',$out,'-w','%{http_code}','-X',$method);if($cookie){$args+=@('-H',"Cookie: sewara_session=$cookie")};if($body){$f=Join-Path $tmpDir 'pelanggan-body.json';[IO.File]::WriteAllText($f,$body,(New-Object Text.UTF8Encoding($false)));$args+=@('-H','Content-Type: application/json','--data-binary',"@$f")};$args+="$apiURL$path";$st=[int](curl.exe @args);return [pscustomobject]@{Status=$st;Body=(Get-Content $out -Raw -ErrorAction SilentlyContinue)}}
function Invoke-Upload([string]$cookie,[hashtable]$fields,[string]$filePath,[string]$mime){$out=Join-Path $tmpDir 'pelanggan-upload.bin';$args=@('-s','--max-time','20','-o',$out,'-w','%{http_code}','-X','POST');if($cookie){$args+=@('-H',"Cookie: sewara_session=$cookie")};foreach($k in $fields.Keys){$args+=@('-F',"$k=$($fields[$k])")};if($filePath){$args+=@('-F',"file=@$filePath;type=$mime")};$args+="$apiURL/api/pelanggan/upload";$st=[int](curl.exe @args);return [pscustomobject]@{Status=$st;Body=(Get-Content $out -Raw -ErrorAction SilentlyContinue)}}
function Invoke-Preflight([string]$path,[string]$origin){$h=curl.exe -s -D - -o NUL --max-time 10 -X OPTIONS -H "Origin: $origin" -H 'Access-Control-Request-Method: GET' "$apiURL$path";return ($h -join ' | ')}
function Get-SessionCookie([string]$email){$jar=Join-Path $tmpDir 'pelanggan-cookie.txt';Remove-Item $jar -ErrorAction SilentlyContinue;$f=Join-Path $tmpDir 'pelanggan-login.json';[IO.File]::WriteAllText($f,"{`"email`":`"$email`",`"password`":`"Rahasia123`"}",(New-Object Text.UTF8Encoding($false)));$st=[int](curl.exe -s --max-time 15 -o NUL -w '%{http_code}' -c $jar -H 'Content-Type: application/json' --data-binary "@$f" "$apiURL/api/auth/login");if($st -ne 200){throw "login gagal HTTP $st"};if((Get-Content $jar -Raw) -match 'sewara_session\s+([^\s]+)'){return $Matches[1]};throw 'cookie tidak ditemukan'}
function Msg($r){try{($r.Body|ConvertFrom-Json).error.message}catch{''}}
$script:results=@();function Add([string]$n,[bool]$ok,[string]$info){$script:results+=,[pscustomobject]@{Name=$n;OK=$ok;Info=$info};Write-Host "$(if($ok){'PASS'}else{'FAIL'}) $n ($info)" -ForegroundColor $(if($ok){'Green'}else{'Red'})}
function Start-Api{$script:api=Start-Process $apiExe -PassThru -WindowStyle Hidden -RedirectStandardOutput (Join-Path $tmpDir 'pelanggan-api.out') -RedirectStandardError (Join-Path $tmpDir 'pelanggan-api.err');for($i=0;$i -lt 40;$i++){Start-Sleep -Milliseconds 300;if((curl.exe -s -o NUL -w '%{http_code}' --max-time 2 "$apiURL/api/health") -eq '200'){return}};throw 'API tidak siap'}
function Stop-Api{if($script:api -and -not $script:api.HasExited){Stop-Process -Id $script:api.Id -Force -ErrorAction SilentlyContinue};$script:api=$null}
$png=Join-Path $tmpDir 'pelanggan.png';[IO.File]::WriteAllBytes($png,[Convert]::FromBase64String('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+M8AAAMBAQDJ/pLvAAAAAElFTkSuQmCC'))
try{
 Push-Location $root;try{$env:CGO_ENABLED='0';go build -o $apiExe ./cmd/api;if($LASTEXITCODE){throw 'go build gagal'}}finally{Pop-Location}
 & (Join-Path $PSScriptRoot 'docker-staging.ps1') reset|Out-Null;& (Join-Path $PSScriptRoot 'docker-staging.ps1') start|Out-Null
