 $idA=Sql "INSERT INTO pelanggan(user_id,nama,hp,hp_normal) VALUES ('$TA','Seed Pool A','','') RETURNING id;";$idB=Sql "INSERT INTO pelanggan(user_id,nama,hp,hp_normal) VALUES ('$TB','Seed Pool B','','') RETURNING id;"
