 $r=Invoke-Api GET '/api/pelanggan' '';Add 'a1 GET tanpa cookie 401' ($r.Status -eq 401) "status=$($r.Status) msg=$(Msg $r)"
 $r=Invoke-Api GET '/api/pelanggan' $a;$j=$r.Body|ConvertFrom-Json;$keys=@('id','nama','hp','hp_normal','alamat','catatan','foto','sumber','updated_at');$shape=$r.Status -eq 200 -and @($j.data.pelanggan|Where-Object{$_.nama -eq 'Riwayat Tanpa HP' -and $_.hp -eq ''}).Count -eq 1 -and $null -ne $j.data.pelanggan -and $j.data.pelanggan -is [array] -and @($j.data.pelanggan|Where-Object{$_.sumber -eq 'pelanggan'}).Count -gt 0 -and @($j.data.pelanggan|Where-Object{$_.sumber -eq 'riwayat'}).Count -gt 0;foreach($p in $j.data.pelanggan){foreach($k in $keys){if($null -eq $p.PSObject.Properties[$k]){$shape=$false}}};Add 'a2 GET owner A 200, bentuk + kedua sumber' $shape "status=$($r.Status)"
 $body='{"nama":"Uji Pelanggan A","hp":"0812-3456-789","alamat":"Jl Uji 1"}';$r=Invoke-Api POST '/api/pelanggan' $a $body;$j=$r.Body|ConvertFrom-Json;$rGet=Invoke-Api GET '/api/pelanggan' $a;$list=($rGet.Body|ConvertFrom-Json).data.pelanggan;$found=@($list|Where-Object{$_.nama -eq 'Uji Pelanggan A'});Add 'b POST upsert + hp_normal' ($r.Status -eq 200 -and $found.Count -eq 1 -and $found[0].hp_normal -eq '68123456789') "status=$($r.Status) hp_normal=$(if($found.Count){$found[0].hp_normal})"
